app_css:
.tool-app-wrapwell { color: #431407; max-width: 960px; margin-inline: auto; }
.tool-app-wrapwell .ww-layout { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 14px; }
.tool-app-wrapwell .ww-panel { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 14px; padding: 16px; }
.tool-app-wrapwell .ww-h { margin: 0 0 10px; font-size: 16px; color: #9a3412; }
.tool-app-wrapwell .ww-form { display: grid; gap: 8px; margin-bottom: 10px; }
.tool-app-wrapwell label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-wrapwell input[type="text"], .tool-app-wrapwell input[type="number"], .tool-app-wrapwell input[type="date"], .tool-app-wrapwell select, .tool-app-wrapwell textarea { border: 1px solid #fdba74; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-wrapwell .ww-btn { background: #C2410C; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-wrapwell .ww-btn:hover { background: #9a3412; }
.tool-app-wrapwell .ww-btn-ghost { background: #ffedd5; color: #C2410C; }
.tool-app-wrapwell .ww-btn-ghost:hover { background: #fed7aa; }
.tool-app-wrapwell .ww-row { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.tool-app-wrapwell .ww-board { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.tool-app-wrapwell .ww-item { background: #fff; border: 1px solid #fdba74; border-radius: 10px; padding: 10px 12px; }
.tool-app-wrapwell .ww-item-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.tool-app-wrapwell .ww-item-head strong { font-size: 14px; }
.tool-app-wrapwell .ww-item-head small { color: #9a3412; }
.tool-app-wrapwell .ww-del { background: none; border: none; color: #b91c1c; font-size: 18px; cursor: pointer; }
.tool-app-wrapwell .ww-bar { height: 8px; background: #ffedd5; border-radius: 99px; margin: 8px 0; overflow: hidden; }
.tool-app-wrapwell .ww-bar i { display: block; height: 100%; background: #C2410C; border-radius: 99px; }
.tool-app-wrapwell .ww-steps { display: grid; gap: 4px; margin-top: 6px; }
.tool-app-wrapwell .ww-steps label { flex-direction: row; align-items: center; font-weight: 400; font-size: 13px; gap: 8px; }
.tool-app-wrapwell .ww-steps input[type="checkbox"] { width: 16px; height: 16px; accent-color: #C2410C; }
.tool-app-wrapwell .ww-steps .ww-done { text-decoration: line-through; color: #9a3412; }
.tool-app-wrapwell .ww-out { background: #fff; border: 1px dashed #fdba74; border-radius: 10px; padding: 12px; font-size: 14px; white-space: pre-wrap; min-height: 80px; margin: 0 0 6px; }
.tool-app-wrapwell .ww-hint { font-size: 12px; color: #9a3412; margin: 8px 0 0; }
.tool-app-wrapwell .ww-wall { list-style: none; padding: 0; margin: 10px 0; display: grid; gap: 8px; }
.tool-app-wrapwell .ww-wall li { background: #fff; border-left: 4px solid #C2410C; border-radius: 0 10px 10px 0; padding: 10px 12px; font-size: 14px; }
.tool-app-wrapwell .ww-wall .ww-who { display: block; margin-top: 6px; font-size: 12px; font-weight: 700; color: #9a3412; }
.tool-app-wrapwell .ww-wall .ww-wdel { float: right; background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 16px; }
.tool-app-wrapwell .ww-empty { font-size: 13px; color: #9a3412; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  var LS = 'toolapp-wrapwell-projects';
  var LT = 'toolapp-wrapwell-testimonials';
  var STEPS = [
    ['deliv', 'Deliverables handed over'],
    ['creds', 'Credentials transferred / revoked'],
    ['invoice', 'Final invoice sent'],
    ['testi', 'Testimonial requested'],
    ['review', 'Review requested'],
    ['refer', 'Referral asked'],
    ['retainer', 'Retainer offered']
  ];
  function load(k) { try { return JSON.parse(localStorage.getItem(k)) || []; } catch (e) { return []; } }
  function save(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
  function uid() { return 'w' + Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36); }
  function daysOverdue(due) {
    if (!due) return 0;
    var today = new Date(); today.setHours(0, 0, 0, 0);
    var d = new Date(due + 'T00:00:00');
    return Math.max(0, Math.floor((today - d) / 864e5));
  }
  function doneCount(p) {
    var n = 0, i;
    for (i = 0; i < STEPS.length; i++) if (p.steps[STEPS[i][0]]) n++;
    return n;
  }
  function renderBoard() {
    var projs = load(LS);
    var ul = $('ww-board');
    ul.innerHTML = '';
    if (!projs.length) {
      var li0 = document.createElement('li');
      li0.className = 'ww-empty';
      li0.textContent = 'No projects yet. Add your first finished project.';
      ul.appendChild(li0);
    }
    projs.forEach(function (p) {
      var li = document.createElement('li');
      li.className = 'ww-item';
      var n = doneCount(p);
      var pct = Math.round(n / STEPS.length * 100);
      var stepsHtml = '';
      STEPS.forEach(function (s) {
        var done = !!p.steps[s[0]];
        stepsHtml += '<label class="' + (done ? 'ww-done' : '') + '">' +
          '<input type="checkbox" data-pid="' + esc(p.id) + '" data-step="' + s[0] + '"' + (done ? ' checked' : '') + '>' +
          esc(s[1]) + '</label>';
      });
      li.innerHTML =
        '<div class="ww-item-head"><div><strong>' + esc(p.client || 'Unnamed client') + '</strong><br>' +
        '<small>' + esc(p.project || 'Untitled project') + ' · ' + n + '/' + STEPS.length + ' done</small></div>' +
        '<button type="button" class="ww-del" data-del="' + esc(p.id) + '" aria-label="Delete project">×</button></div>' +
        '<div class="ww-bar"><i style="width:' + pct + '%"></i></div>' +
        '<div class="ww-steps">' + stepsHtml + '</div>';
      ul.appendChild(li);
    });
    renderSelects(projs);
  }
  function renderSelects(projs) {
    var opts = projs.map(function (p) {
      return '<option value="' + esc(p.id) + '">' + esc(p.client || 'Unnamed') + ' — ' + esc(p.project || 'Untitled') + '</option>';
    }).join('');
    var sel = $('ww-sel'), inv = $('ww-invsel');
    var prevSel = sel.value, prevInv = inv.value;
    if (opts) {
      sel.innerHTML = opts; inv.innerHTML = opts;
      if (prevSel) sel.value = prevSel;
      if (prevInv) inv.value = prevInv;
    } else {
      sel.innerHTML = '<option value="">— add a project first —</option>';
      inv.innerHTML = '<option value="">— add a project first —</option>';
    }
  }
  function findProj(id) {
    var projs = load(LS);
    for (var i = 0; i < projs.length; i++) if (projs[i].id === id) return projs[i];
    return null;
  }
  function messageFor(stage, p) {
    var client = p.client || 'there';
    var proj = p.project || 'the project';
    if (stage === 't') {
      return 'Hi ' + client + ',\n\n' + proj + ' is all wrapped up on my end — thank you again for trusting me with it.\n\n' +
        'I\'m collecting a few words from recent clients. Would you be open to answering three quick questions?\n' +
        '1. What problem were you trying to solve when we started?\n' +
        '2. What stood out about working together?\n' +
        '3. What would you tell someone considering hiring me?\n\n' +
        'Even two or three sentences each is perfect. Thanks so much.';
    }
    if (stage === 'r') {
      return 'Hi ' + client + ',\n\nQuick nudge — if you have sixty seconds, a short review of our work on ' + proj + ' would mean a lot. No pressure at all, and thanks again for a great project.';
    }
    if (stage === 'f') {
      return 'Hi ' + client + ',\n\nHope ' + proj + ' is serving you well. Quick question — do you know anyone else who might need help like this? I\'d love an introduction, and I take good care of referrals.';
    }
    return 'Hi ' + client + ',\n\nIt\'s been about a month since we wrapped ' + proj + '. A lot of my clients find a small monthly retainer handy for ongoing tweaks and support — would you like me to put together a simple option for you?';
  }
  function copyText(t) {
    function done() {}
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t).then(done, function () { fallback(); });
    } else { fallback(); }
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = t;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(ta);
    }
  }
  function renderWall() {
    var ts = load(LT);
    var ul = $('ww-wall');
    ul.innerHTML = '';
    if (!ts.length) {
      var li0 = document.createElement('li');
      li0.className = 'ww-empty';
      li0.textContent = 'No testimonials yet. Ask, then paste the answers here.';
      ul.appendChild(li0);
      return;
    }
    ts.forEach(function (t) {
      var li = document.createElement('li');
      li.innerHTML = '<button type="button" class="ww-wdel" data-tdel="' + esc(t.id) + '" aria-label="Delete">×</button>' +
        '“' + esc(t.quote) + '”<span class="ww-who">— ' + esc(t.client) + '</span>';
      ul.appendChild(li);
    });
  }
  function embedCode() {
    var ts = load(LT);
    var out = '<div style="font-family:system-ui,sans-serif;max-width:640px">';
    ts.forEach(function (t) {
      out += '<blockquote style="border-left:4px solid #C2410C;padding:8px 16px;margin:0 0 16px;color:#431407">' +
        esc(t.quote) + '<br><strong>— ' + esc(t.client) + '</strong></blockquote>';
    });
    return out + '</div>';
  }
  var root = $('toolAppRoot');
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'ww-add') {
      var projs = load(LS);
      var steps = {};
      STEPS.forEach(function (s) { steps[s[0]] = false; });
      projs.unshift({
        id: uid(),
        client: $('ww-client').value.trim(),
        project: $('ww-project').value.trim(),
        finished: $('ww-finished').value,
        amount: parseFloat($('ww-amount').value) || 0,
        duedate: $('ww-duedate').value,
        paid: false,
        steps: steps
      });
      save(LS, projs);
      $('ww-client').value = ''; $('ww-project').value = '';
      $('ww-finished').value = ''; $('ww-amount').value = ''; $('ww-duedate').value = '';
      renderBoard();
      return;
    }
    if (t.getAttribute && t.getAttribute('data-del')) {
      var ps = load(LS).filter(function (p) { return p.id !== t.getAttribute('data-del'); });
      save(LS, ps);
      renderBoard();
      return;
    }
    if (t.getAttribute && t.getAttribute('data-tdel')) {
      var ts = load(LT).filter(function (x) { return x.id !== t.getAttribute('data-tdel'); });
      save(LT, ts);
      renderWall();
      return;
    }
    if (t.id === 'ww-gen') {
      var p = findProj($('ww-sel').value);
      if (!p) { $('ww-out').textContent = 'Add a project first.'; return; }
      $('ww-out').textContent = messageFor($('ww-stage').value, p);
      return;
    }
    if (t.id === 'ww-copy') { copyText($('ww-out').textContent); return; }
    if (t.id === 'ww-tadd') {
      var quote = $('ww-tquote').value.trim();
      if (!quote) return;
      var all = load(LT);
      all.unshift({ id: uid(), client: $('ww-tclient').value.trim() || 'Client', quote: quote });
      save(LT, all);
      $('ww-tclient').value = ''; $('ww-tquote').value = '';
      renderWall();
      return;
    }
    if (t.id === 'ww-embed') { copyText(embedCode()); return; }
    if (t.id === 'ww-nudge') {
      var np = findProj($('ww-invsel').value);
      if (!np) { $('ww-invout').textContent = 'Add a project first.'; return; }
      if (np.paid) { $('ww-invout').textContent = 'This invoice is marked paid. Nothing to nudge.'; return; }
      var d = daysOverdue(np.duedate);
      var when = np.duedate ? ('due on ' + np.duedate + (d > 0 ? ', ' + d + ' day' + (d === 1 ? '' : 's') + ' ago' : ' (today)')) : 'with no due date set';
      $('ww-invout').textContent = 'Hi ' + (np.client || 'there') + ',\n\nJust a friendly check — the final invoice for ' +
        (np.project || 'the project') + ' (' + money(np.amount) + ') was ' + when + '.\n\n' +
        'Could you confirm it\'s on the way? Happy to resend the invoice if it got lost in the shuffle. Thanks!';
      return;
    }
    if (t.id === 'ww-paid') {
      var mp = findProj($('ww-invsel').value);
      if (!mp) return;
      var allp = load(LS);
      for (var i = 0; i < allp.length; i++) if (allp[i].id === mp.id) allp[i].paid = true;
      save(LS, allp);
      $('ww-invout').textContent = 'Marked paid. Nice — that project is fully closed out.';
    }
  });
  root.addEventListener('change', function (e) {
    var t = e.target;
    if (t.getAttribute && t.getAttribute('data-step')) {
      var allp = load(LS);
      for (var i = 0; i < allp.length; i++) {
        if (allp[i].id === t.getAttribute('data-pid')) {
          allp[i].steps[t.getAttribute('data-step')] = t.checked;
        }
      }
      save(LS, allp);
      renderBoard();
    }
  });
  (function init() {
    renderBoard();
    renderWall();
    var today = new Date().toISOString().slice(0, 10);
    $('ww-finished').value = today;
  })();
})();
